import patronageData from "@/lib/data/patronage.json";
import { canonicalSaintSlug, getBiographyReview, reviews } from "@/lib/saint-reviews";

// Generated by scripts/build-patronage.mjs from patron_of in saints.json.
export interface PatronTopic {
  slug: string;
  label: string;
  saints: string[];
}

export interface PatronLink {
  slug: string;
  label: string;
}

const data = patronageData as {
  topics: PatronTopic[];
  bySaint: Record<string, PatronLink[]>;
};

// Split a reviewed patronage list. A leading "and" or "or" belongs to the
// previous comma, as in "agricultural laborers, and Madrid".
function patronFragments(value: string | null | undefined): string[] {
  return (value ?? "")
    .split(/[,;]/)
    .map(fragment => fragment.trim().toLowerCase().replace(/^(?:and|or)\s+/, "").trim())
    .filter(Boolean);
}

function reviewNamesTopic(slug: string, label: string): boolean {
  const review = getBiographyReview(slug);
  return review?.status === "source-reviewed"
    && review.kind === "saint"
    && patronFragments(review.patron_of).includes(label);
}

const saintsByPatronLabel = new Map<string, string[]>();
for (const slug of Object.keys(reviews)) {
  if (canonicalSaintSlug(slug) !== slug) continue;
  const review = getBiographyReview(slug);
  if (!review || review.status !== "source-reviewed" || review.kind !== "saint") continue;
  for (const fragment of new Set(patronFragments(review.patron_of))) {
    const matches = saintsByPatronLabel.get(fragment);
    if (matches) matches.push(slug);
    else saintsByPatronLabel.set(fragment, [slug]);
  }
}

// Keep a topic only when a source-reviewed biography names it. The generated
// index supplies the topic list and the original order; reviewed patron_of
// text can add a saint the generator omitted and can drop a claim it invented.
export const PATRON_TOPICS: PatronTopic[] = data.topics.map(topic => {
  const label = topic.label.toLowerCase();
  const saints: string[] = [];
  const seen = new Set<string>();
  for (const slug of topic.saints.map(canonicalSaintSlug)) {
    if (seen.has(slug) || !reviewNamesTopic(slug, label)) continue;
    seen.add(slug);
    saints.push(slug);
  }
  for (const slug of [...(saintsByPatronLabel.get(label) ?? [])].sort()) {
    if (seen.has(slug)) continue;
    seen.add(slug);
    saints.push(slug);
  }
  return { ...topic, saints };
}).filter(topic => topic.saints.length > 0);

const TOPIC_BY_SLUG = new Map(PATRON_TOPICS.map((t) => [t.slug, t]));

// Editorial shortcuts to supported topics, complementing the everyday-life guides.
export const FEATURED_PATRON_SLUGS = [
  "cancer-patients", "children", "cooks", "farmers", "firefighters",
  "gardeners", "hospitals", "immigrants", "lawyers", "prisoners",
];

export const FEATURED_PATRON_TOPICS = FEATURED_PATRON_SLUGS
  .map(slug => TOPIC_BY_SLUG.get(slug))
  .filter((topic): topic is PatronTopic => Boolean(topic));

export function getTopicBySlug(slug: string): PatronTopic | null {
  return TOPIC_BY_SLUG.get(slug) ?? null;
}

export function getPatronLinksForSaint(saintSlug: string): PatronLink[] {
  return PATRON_TOPICS.filter(topic => topic.saints.includes(canonicalSaintSlug(saintSlug)))
    .map(({ slug, label }) => ({ slug, label }));
}

const SMALL_WORDS = new Set([
  "of", "the", "and", "in", "for", "a", "an", "to", "with", "from", "against",
]);

// "the sick" -> "the Sick" (first word keeps its article casing when small),
// existing capitals (England, HIV/AIDS, St. Petersburg) are preserved.
export function titleCaseLabel(label: string): string {
  return label
    .split(" ")
    .map((word, i) =>
      SMALL_WORDS.has(word.toLowerCase()) && i > 0
        ? word.toLowerCase()
        : word.charAt(0).toUpperCase() + word.slice(1)
    )
    .join(" ");
}

// Catholic convention: patronage "against pestilence" reads
// "Patron Saint Against Pestilence", everything else "Patron Saint(s) of X".
export function topicTitle(topic: PatronTopic): string {
  const plural = topic.saints.length > 1 ? "Patron Saints" : "Patron Saint";
  if (topic.label.toLowerCase().startsWith("against ")) {
    return `${plural} Against ${titleCaseLabel(topic.label.slice(8))}`;
  }
  return `${plural} of ${titleCaseLabel(topic.label)}`;
}
